IMG = ['planner', 'generating', 'overview', 'day', 'map', 'dashboard', 'reels']


def to_tr(html: str) -> str:
    for en, tr in PAIRS:
        n = html.count(en)
        assert n >= 1, f'çeviri anahtarı bulunamadı: {en[:70]}'
        html = html.replace(en, tr)
    for k in IMG:
        html = html.replace(f'img/{k}.webp', f'img/tr-{k}.webp')
    return html
